import{_ as c,C as l,o,c as u,a2 as r,b as t,w as a,a as s,E as d,a3 as n}from"./chunks/framework.CgxQ0r6v.js";const A=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-VI/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-VI/Lectura_Catedra_Evaluacion_1.md"}'),p={name:"materias/Proyecto_Sociotecnologico_II/documentacion/II-VI/Lectura_Catedra_Evaluacion_1.md"};function b(m,e,g,h,f,C){const i=l("Mermaid");return o(),u("div",null,[e[2]||(e[2]=r('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-vi" tabindex="-1">Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre VI) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-vi" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre VI)&quot;">​</a></h2><h3 id="eje-tematico-planificacion-y-aplicacion-de-pruebas-de-software-qa" tabindex="-1">Eje Temático: Planificación y Aplicación de Pruebas de Software (QA) <a class="header-anchor" href="#eje-tematico-planificacion-y-aplicacion-de-pruebas-de-software-qa" aria-label="Permalink to &quot;Eje Temático: Planificación y Aplicación de Pruebas de Software (QA)&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-calidad-como-compromiso-comunitario" tabindex="-1">🧭 Introducción: La Calidad como Compromiso Comunitario <a class="header-anchor" href="#🧭-introduccion-la-calidad-como-compromiso-comunitario" aria-label="Permalink to &quot;🧭 Introducción: La Calidad como Compromiso Comunitario&quot;">​</a></h2><p>En la fase final del desarrollo de software, ningún sistema debe entregarse a una comunidad u organización sin haber sido sometido a un proceso metódico de <strong>Aseguramiento de Calidad (Quality Assurance - QA)</strong> y pruebas funcionales.</p><p>Un error no detectado en un sistema comunitario puede tener consecuencias graves: la pérdida del expediente médico de un niño en un ambulatorio, el cobro indebido de una bolsa de alimentos en un consejo comunal, o la paralización de las inscripciones en una escuela básica.</p><p>En el Trimestre VI de PST II, los estudiantes asumen el rol de analistas de calidad, diseñando matrices de prueba estructuradas para garantizar que la aplicación informática sea robusta, confiable y segura.</p><hr><h2 id="🏛️-capitulo-i-niveles-y-tipos-de-pruebas-de-software" tabindex="-1">🏛️ CAPÍTULO I: Niveles y Tipos de Pruebas de Software <a class="header-anchor" href="#🏛️-capitulo-i-niveles-y-tipos-de-pruebas-de-software" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Niveles y Tipos de Pruebas de Software&quot;">​</a></h2><p>Las pruebas de software se organizan en distintos niveles a lo largo del ciclo de vida:</p>',11)),(o(),t(n,null,{default:a(()=>[d(i,{id:"mermaid-29",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20NIVELES%20%5B%22%F0%9F%8F%97%EF%B8%8F%20Pir%C3%A1mide%20de%20Niveles%20de%20Prueba%22%5D%0A%20%20%20%20%20%20%20%20U%5B%221.%20Pruebas%20Unitarias%20(Funciones%20y%20M%C3%A9todos%20Aislados)%22%5D%0A%20%20%20%20%20%20%20%20I%5B%222.%20Pruebas%20de%20Integraci%C3%B3n%20(Conexi%C3%B3n%20entre%20M%C3%B3dulos%20y%20BD)%22%5D%0A%20%20%20%20%20%20%20%20S%5B%223.%20Pruebas%20de%20Sistema%20(Flujo%20Completo%20de%20la%20Aplicaci%C3%B3n)%22%5D%0A%20%20%20%20%20%20%20%20A%5B%224.%20Pruebas%20de%20Aceptaci%C3%B3n%20con%20el%20Usuario%20(UAT%20en%20Comunidad)%22%5D%0A%20%20%20%20%20%20%20%20U%20--%3E%20I%0A%20%20%20%20%20%20%20%20I%20--%3E%20S%0A%20%20%20%20%20%20%20%20S%20--%3E%20A%0A%20%20%20%20end%0A%0A%20%20%20%20style%20U%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20I%20fill%3A%230369a1%2Cstroke%3A%230ea5e9%2Ccolor%3A%23fff%0A%20%20%20%20style%20S%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20A%20fill%3A%2315803d%2Cstroke%3A%2322c55e%2Ccolor%3A%23fff%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r('<h3 id="_1-1-pruebas-de-caja-negra-black-box-testing" tabindex="-1">1.1 Pruebas de Caja Negra (Black Box Testing) <a class="header-anchor" href="#_1-1-pruebas-de-caja-negra-black-box-testing" aria-label="Permalink to &quot;1.1 Pruebas de Caja Negra (Black Box Testing)&quot;">​</a></h3><p>Es la técnica principal aplicada en PST II. El evaluador prueba las funcionalidades del sistema <strong>sin necesidad de conocer el código fuente interno</strong>, concentrándose únicamente en:</p><ul><li>¿Qué entradas (<em>inputs</em>) se envían al formulario?</li><li>¿Qué salidas (<em>outputs</em>) y comportamientos devuelve el sistema?</li><li>¿Cumple con lo especificado en los Requerimientos Funcionales (RF)?</li></ul><h3 id="_1-2-pruebas-de-caja-blanca-white-box-testing" tabindex="-1">1.2 Pruebas de Caja Blanca (White Box Testing) <a class="header-anchor" href="#_1-2-pruebas-de-caja-blanca-white-box-testing" aria-label="Permalink to &quot;1.2 Pruebas de Caja Blanca (White Box Testing)&quot;">​</a></h3><p>Se enfocan en la lógica interna del código: revisión de estructuras condicionales (<code>if/else</code>), bucles, manejo de excepciones (<code>try/catch</code>) y cobertura de sentencias.</p><hr><h2 id="📋-capitulo-ii-diseno-de-casos-de-prueba-test-cases" tabindex="-1">📋 CAPÍTULO II: Diseño de Casos de Prueba (Test Cases) <a class="header-anchor" href="#📋-capitulo-ii-diseno-de-casos-de-prueba-test-cases" aria-label="Permalink to &quot;📋 CAPÍTULO II: Diseño de Casos de Prueba (Test Cases)&quot;">​</a></h2><p>Un <strong>Caso de Prueba</strong> es un conjunto de condiciones o variables bajo las cuales un evaluador determina si una aplicación informática funciona correctamente.</p><h3 id="_2-1-tecnicas-de-diseno-de-casos-de-prueba" tabindex="-1">2.1 Técnicas de Diseño de Casos de Prueba <a class="header-anchor" href="#_2-1-tecnicas-de-diseno-de-casos-de-prueba" aria-label="Permalink to &quot;2.1 Técnicas de Diseño de Casos de Prueba&quot;">​</a></h3><ol><li><strong>Partición de Equivalencia:</strong> Dividir las entradas posibles en clases válidas e inválidas (ej: un campo edad solo acepta enteros positivos entre 0 y 120).</li><li><strong>Análisis de Valores Límite:</strong> Probar los extremos del rango donde suelen ocurrir la mayoría de los errores (ej: probar con -1, 0, 1, 119, 120, 121).</li><li><strong>Prueba de Inyección de Caracteres Especiales:</strong> Introducir comillas simples (<code>&#39;</code>), etiquetas HTML (<code>&lt;script&gt;</code>) o cadenas vacías para verificar que el sistema no colapse.</li></ol><h3 id="_2-2-ficha-estandar-de-caso-de-prueba" tabindex="-1">2.2 Ficha Estándar de Caso de Prueba <a class="header-anchor" href="#_2-2-ficha-estandar-de-caso-de-prueba" aria-label="Permalink to &quot;2.2 Ficha Estándar de Caso de Prueba&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID Caso de Prueba:</th><th><code>CP-AUTH-01</code></th><th>Módulo Asociado:</th><th>Seguridad / Autenticación</th></tr></thead><tbody><tr><td><strong>Requerimiento Validado:</strong></td><td><code>RF-01</code>: Autenticación con roles</td><td><strong>Prioridad:</strong></td><td>Alta</td></tr><tr><td><strong>Descripción:</strong></td><td>Verificar el inicio de sesión exitoso con credenciales válidas de operador.</td><td></td><td></td></tr><tr><td><strong>Precondición:</strong></td><td>Usuario <code>operador1</code> registrado activamente en base de datos.</td><td></td><td></td></tr><tr><td><strong>Datos de Prueba (Inputs):</strong></td><td>Usuario: <code>operador1</code> | Contraseña: <code>ClaveSegura2026*</code></td><td></td><td></td></tr><tr><td><strong>Pasos de Ejecución:</strong></td><td>1. Navegar a la URL de login.<br>2. Ingresar usuario y contraseña en los campos correspondientes.<br>3. Presionar el botón &#39;Ingresar&#39;.</td><td></td><td></td></tr><tr><td><strong>Resultado Esperado:</strong></td><td>Redirección inmediata al panel principal del operador; bienvenida personalizada en pantalla; menú administrativo deshabilitado.</td><td></td><td></td></tr><tr><td><strong>Resultado Obtenido:</strong></td><td>Redirección exitosa en 0.8 segundos. Menú administrativo oculto correctamente.</td><td></td><td></td></tr><tr><td><strong>Estado:</strong></td><td><strong>APROBADO (PASSED)</strong></td><td></td><td></td></tr></tbody></table><hr><h2 id="📊-capitulo-iii-la-matriz-de-control-de-pruebas-e-incidencias" tabindex="-1">📊 CAPÍTULO III: La Matriz de Control de Pruebas e Incidencias <a class="header-anchor" href="#📊-capitulo-iii-la-matriz-de-control-de-pruebas-e-incidencias" aria-label="Permalink to &quot;📊 CAPÍTULO III: La Matriz de Control de Pruebas e Incidencias&quot;">​</a></h2><p>El equipo debe consolidar los resultados de todas las pruebas en una <strong>Matriz de Control</strong>, clasificando las incidencias o fallas encontradas:</p><h3 id="clasificacion-de-severidad-de-errores" tabindex="-1">Clasificación de Severidad de Errores: <a class="header-anchor" href="#clasificacion-de-severidad-de-errores" aria-label="Permalink to &quot;Clasificación de Severidad de Errores:&quot;">​</a></h3><ul><li><strong>Crítico (Bloqueante):</strong> El sistema colapsa, la base de datos se corrompe o los datos no se guardan. Impide la entrega.</li><li><strong>Mayor:</strong> Una funcionalidad principal no responde según el requerimiento, pero el resto del sistema sigue operando.</li><li><strong>Menor / Cosmético:</strong> Errores ortográficos, desalineación visual de un botón o colores poco contrastantes.</li></ul>',17)),(o(),t(n,null,{default:a(()=>[d(i,{id:"mermaid-248",class:"mermaid",graph:"pie%20title%20Distribuci%C3%B3n%20T%C3%ADpica%20de%20Hallazgos%20en%20Pruebas%20PST%20II%0A%20%20%20%20%22Casos%20Aprobados%20(Sin%20Error)%22%20%3A%2075%0A%20%20%20%20%22Errores%20Menores%20(Visuales)%22%20%3A%2015%0A%20%20%20%20%22Errores%20Mayores%20(L%C3%B3gica%20corregida)%22%20%3A%208%0A%20%20%20%20%22Errores%20Cr%C3%ADticos%20(Bloqueantes%20resueltos)%22%20%3A%202%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<hr><h2 id="🔧-capitulo-iv-correccion-de-errores-y-pruebas-de-regresion" tabindex="-1">🔧 CAPÍTULO IV: Corrección de Errores y Pruebas de Regresión <a class="header-anchor" href="#🔧-capitulo-iv-correccion-de-errores-y-pruebas-de-regresion" aria-label="Permalink to &quot;🔧 CAPÍTULO IV: Corrección de Errores y Pruebas de Regresión&quot;">​</a></h2><p>Cuando se detecta un error y el programador modifica el código para resolverlo, surge un nuevo riesgo: <strong>romper algo que antes sí funcionaba</strong>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Pruebas de Regresión:</strong> Cada vez que se corrija un error crítico o se modifique una consulta SQL en el Trimestre VI, el equipo debe volver a ejecutar los casos de prueba de los módulos adyacentes para garantizar la estabilidad total del sistema antes de llevarlo a la comunidad.</p></div><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-1" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 1 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-1" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 1&quot;">​</a></h2><p>Para la Evaluación 1 del Trimestre VI, el equipo presentará el <strong>Dossier de Calidad de Software</strong>:</p><ol><li><strong>Catálogo de Casos de Prueba (Mínimo 15 a 20 casos):</strong> Cubriendo todos los requerimientos funcionales del sistema.</li><li><strong>Matriz de Ejecución de Pruebas:</strong> Con indicación de fecha, evaluador responsable y estado (Aprobado/Fallido).</li><li><strong>Registro de Corrección de Errores:</strong> Evidencia de los problemas detectados y cómo fueron solucionados en el código.</li></ol>',8))])}const I=c(p,[["render",b]]);export{A as __pageData,I as default};
